def has_close_elements(numbers: List[float], threshold: float) -> bool:
    numbers.sort()
    for i in range(len(numbers) - 1):
        if abs(numbers[i] - numbers[i + 1]) < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    balance = 0

    for char in paren_string.replace(" ", ""):
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        current_group.append(char)

        if balance == 0 and current_group:
            result.append(''.join(current_group))
            current_group = []

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            for k in range(min(i + j + 1, N)):
                l = i + j - k
                if i > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][k])
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][l-1] + grid[i][l])
                if j > 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[k][j])
                    if l > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][l-1] + grid[l][j])
                if i > 0 and j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j-1][k] + grid[i][k] + grid[l][j])

    return dp[N-1][N-1][N-1] if dp[N-1][N-1][N-1] != -float('inf') else 0

def find_number_combinations():
    def is_unique(n1, n2, n3):
        digits = str(n1) + str(n2) + str(n3)
        return len(set(digits)) == len(digits)

    combinations = []
    for n1 in range(123, 334):  # 334 because 3*333 = 999 which is the max possible value
        n2 = 2 * n1
        n3 = 3 * n1
        if n2 > 999 or n3 > 999:
            break
        if is_unique(n1, n2, n3):
            combinations.append((n1, n2, n3))
    return combinations

def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("n must be between 1 and 50, inclusive")

    factorial = 1
    sum_factorials = 0

    for i in range(1, n + 1):
        factorial *= i
        sum_factorials += factorial

    return sum_factorials

def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        return f"{N}/{level - N + 1}"
    else:
        return f"{level - N + 1}/{N}"

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_prod = 0
        for i in range(start + 1, N - k + 1):
            left = int(num_str[start:i])
            right = helper(i, k - 1)
            max_prod = max(max_prod, left * right)
        return max_prod

    return helper(0, K)

