def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for time, value in herbs:
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (V + 1)
    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)
    return V - dp[V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        return chr((ord(c) - ord(k) + 26) % 26 + ord('a'))

    key = key.lower()
    ciphertext = ciphertext.lower()
    key_length = len(key)
    decrypted_text = []

    for i, char in enumerate(ciphertext):
        key_char = key[i % key_length]
        decrypted_text.append(shift_char(char, key_char))

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0
    for i, (school_hours, extra_hours) in enumerate(schedule, start=1):
        total_hours = school_hours + extra_hours
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = i
    return most_unhappy_day

